CREATE TABLE IF NOT EXISTS runtime_instances ( instance_id TEXT PRIMARY KEY, scenario TEXT NOT NULL, build_identity TEXT NOT NULL DEFAULT '', runtime_release_id TEXT NOT NULL DEFAULT '', runtime_release_operation_id TEXT NOT NULL DEFAULT '', start_operation_id TEXT NOT NULL DEFAULT '', variant TEXT NOT NULL DEFAULT 'live', generation INTEGER NOT NULL, scope_path TEXT NOT NULL DEFAULT '', sandbox_id TEXT NOT NULL DEFAULT '', status TEXT NOT NULL, phase TEXT NOT NULL DEFAULT '', started_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_heartbeat_at TEXT, heartbeat_deadline_at TEXT, stopped_at TEXT, stop_reason TEXT NOT NULL DEFAULT '', owner_kind TEXT NOT NULL DEFAULT 'lifecycle', owner_pid INTEGER, working_dir TEXT NOT NULL DEFAULT '', host_boot_id TEXT NOT NULL DEFAULT '', host_session_id TEXT NOT NULL DEFAULT '', supervisor_id TEXT NOT NULL DEFAULT '', supervised_at TEXT, last_reconciled_at TEXT, reconciliation_status TEXT NOT NULL DEFAULT '', reconciliation_reason TEXT NOT NULL DEFAULT '', supervision_policy TEXT NOT NULL DEFAULT 'managed', schema_version INTEGER NOT NULL, UNIQUE(scenario, variant, generation) ); CREATE INDEX IF NOT EXISTS idx_runtime_instances_scenario ON runtime_instances(scenario); CREATE INDEX IF NOT EXISTS idx_runtime_instances_scenario_variant ON runtime_instances(scenario, variant); CREATE INDEX IF NOT EXISTS idx_runtime_instances_status ON runtime_instances(status); CREATE INDEX IF NOT EXISTS idx_runtime_instances_heartbeat_deadline ON runtime_instances(heartbeat_deadline_at); CREATE INDEX IF NOT EXISTS idx_runtime_instances_host_boot ON runtime_instances(host_boot_id); CREATE INDEX IF NOT EXISTS idx_runtime_instances_supervisor ON runtime_instances(supervisor_id); CREATE INDEX IF NOT EXISTS idx_runtime_instances_reconcile ON runtime_instances(reconciliation_status, last_reconciled_at); CREATE TABLE IF NOT EXISTS runtime_supervisor_sessions ( supervisor_id TEXT PRIMARY KEY, host_boot_id TEXT NOT NULL, host_session_id TEXT NOT NULL, pid INTEGER, status TEXT NOT NULL, started_at TEXT NOT NULL, last_heartbeat_at TEXT NOT NULL, heartbeat_deadline_at TEXT NOT NULL, stopped_at TEXT, stop_reason TEXT NOT NULL DEFAULT '', version TEXT NOT NULL DEFAULT '', metadata_json TEXT NOT NULL DEFAULT '' ); CREATE INDEX IF NOT EXISTS idx_runtime_supervisor_sessions_status ON runtime_supervisor_sessions(status); CREATE INDEX IF NOT EXISTS idx_runtime_supervisor_sessions_deadline ON runtime_supervisor_sessions(heartbeat_deadline_at); CREATE TABLE IF NOT EXISTS runtime_port_claims ( claim_id TEXT PRIMARY KEY, instance_id TEXT NOT NULL, scenario TEXT NOT NULL, variant TEXT NOT NULL DEFAULT 'live', port_name TEXT NOT NULL DEFAULT '', env_var TEXT NOT NULL DEFAULT '', port INTEGER NOT NULL, bind_host TEXT NOT NULL DEFAULT '127.0.0.1', url TEXT NOT NULL DEFAULT '', status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, expires_at TEXT, last_bound_at TEXT, last_listener_check_at TEXT, last_listener_seen_at TEXT, first_unbound_at TEXT, consecutive_listener_misses INTEGER NOT NULL DEFAULT 0, listener_status TEXT NOT NULL DEFAULT 'unknown', listener_pid INTEGER, listener_process_label TEXT NOT NULL DEFAULT '', FOREIGN KEY(instance_id) REFERENCES runtime_instances(instance_id) ON DELETE CASCADE ); CREATE INDEX IF NOT EXISTS idx_runtime_port_claims_instance ON runtime_port_claims(instance_id); CREATE INDEX IF NOT EXISTS idx_runtime_port_claims_scenario ON runtime_port_claims(scenario); CREATE INDEX IF NOT EXISTS idx_runtime_port_claims_scenario_variant ON runtime_port_claims(scenario, variant); CREATE INDEX IF NOT EXISTS idx_runtime_port_claims_status ON runtime_port_claims(status); CREATE INDEX IF NOT EXISTS idx_runtime_port_claims_expiry ON runtime_port_claims(expires_at); CREATE UNIQUE INDEX IF NOT EXISTS idx_runtime_port_claims_active_port ON runtime_port_claims(port, bind_host) WHERE status IN ('reserved', 'bound'); CREATE TABLE IF NOT EXISTS runtime_health_snapshots ( instance_id TEXT PRIMARY KEY, scenario TEXT NOT NULL, build_identity TEXT NOT NULL DEFAULT '', runtime_release_id TEXT NOT NULL DEFAULT '', runtime_release_operation_id TEXT NOT NULL DEFAULT '', start_operation_id TEXT NOT NULL DEFAULT '', status TEXT NOT NULL, readiness INTEGER, checked_at TEXT, latency_ms INTEGER, error TEXT NOT NULL DEFAULT '', response_json TEXT NOT NULL DEFAULT '', schema_valid INTEGER, FOREIGN KEY(instance_id) REFERENCES runtime_instances(instance_id) ON DELETE CASCADE ); CREATE INDEX IF NOT EXISTS idx_runtime_health_snapshots_scenario ON runtime_health_snapshots(scenario); CREATE TABLE IF NOT EXISTS runtime_process_refs ( ref_id TEXT PRIMARY KEY, instance_id TEXT NOT NULL, pid INTEGER, pgid INTEGER, process_id TEXT NOT NULL DEFAULT '', step TEXT NOT NULL DEFAULT '', command TEXT NOT NULL DEFAULT '', log_file TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT '', started_at TEXT NOT NULL, ended_at TEXT, host_boot_id TEXT NOT NULL DEFAULT '', FOREIGN KEY(instance_id) REFERENCES runtime_instances(instance_id) ON DELETE CASCADE ); CREATE INDEX IF NOT EXISTS idx_runtime_process_refs_instance ON runtime_process_refs(instance_id); CREATE INDEX IF NOT EXISTS idx_runtime_process_refs_pid ON runtime_process_refs(pid); CREATE TABLE IF NOT EXISTS runtime_events ( event_id TEXT PRIMARY KEY, instance_id TEXT, scenario TEXT NOT NULL DEFAULT '', event_type TEXT NOT NULL, created_at TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '', FOREIGN KEY(instance_id) REFERENCES runtime_instances(instance_id) ON DELETE SET NULL ); CREATE INDEX IF NOT EXISTS idx_runtime_events_instance ON runtime_events(instance_id); CREATE INDEX IF NOT EXISTS idx_runtime_events_scenario ON runtime_events(scenario); CREATE INDEX IF NOT EXISTS idx_runtime_events_type ON runtime_events(event_type); CREATE TABLE IF NOT EXISTS runtime_start_operations ( operation_id TEXT PRIMARY KEY, fence_operation_id TEXT NOT NULL DEFAULT '', scenario TEXT NOT NULL, variant TEXT NOT NULL DEFAULT 'live', operation TEXT NOT NULL DEFAULT 'start', status TEXT NOT NULL, verdict TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', initiator_pid INTEGER, initiator_argv TEXT NOT NULL DEFAULT '', initiator_parent_pid INTEGER, initiator_parent_argv TEXT NOT NULL DEFAULT '', initiator_scope TEXT NOT NULL DEFAULT '', started_at TEXT NOT NULL, updated_at TEXT NOT NULL, finished_at TEXT, current_step TEXT NOT NULL DEFAULT '', dependency_current TEXT NOT NULL DEFAULT '', dependency_index INTEGER NOT NULL DEFAULT 0, dependency_total INTEGER NOT NULL DEFAULT 0, steps_json TEXT NOT NULL DEFAULT '' ); CREATE INDEX IF NOT EXISTS idx_runtime_start_operations_scenario_variant ON runtime_start_operations(scenario, variant); CREATE INDEX IF NOT EXISTS idx_runtime_start_operations_status ON runtime_start_operations(status); CREATE TABLE IF NOT EXISTS runtime_phase_durations ( scenario TEXT NOT NULL, variant TEXT NOT NULL DEFAULT 'live', phase TEXT NOT NULL, duration_ms INTEGER NOT NULL, recorded_at TEXT NOT NULL ); CREATE INDEX IF NOT EXISTS idx_runtime_phase_durations_key ON runtime_phase_durations(scenario, variant, phase); CREATE TABLE IF NOT EXISTS runtime_recovery_policies ( scenario TEXT NOT NULL, variant TEXT NOT NULL DEFAULT 'live', critical INTEGER NOT NULL DEFAULT 0, dependency_tier INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 0, retry_budget INTEGER NOT NULL DEFAULT 0, opt_out INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY (scenario, variant) ); CREATE INDEX IF NOT EXISTS idx_runtime_recovery_policies_enabled ON runtime_recovery_policies(enabled, critical, opt_out, dependency_tier); CREATE TABLE IF NOT EXISTS runtime_pressure_epochs ( epoch_id TEXT PRIMARY KEY, status TEXT NOT NULL, source TEXT NOT NULL DEFAULT '', detected_at TEXT NOT NULL, cleared_at TEXT, updated_at TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '' ); CREATE INDEX IF NOT EXISTS idx_runtime_pressure_epochs_status ON runtime_pressure_epochs(status, detected_at DESC); CREATE TABLE IF NOT EXISTS runtime_recovery_decisions ( decision_id TEXT PRIMARY KEY, epoch_id TEXT NOT NULL, scenario TEXT NOT NULL, variant TEXT NOT NULL DEFAULT 'live', state TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', attempt INTEGER NOT NULL DEFAULT 0, cooldown_until TEXT, idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '', FOREIGN KEY(epoch_id) REFERENCES runtime_pressure_epochs(epoch_id) ON DELETE CASCADE, UNIQUE(idempotency_key) ); CREATE INDEX IF NOT EXISTS idx_runtime_recovery_decisions_epoch ON runtime_recovery_decisions(epoch_id, created_at DESC); CREATE INDEX IF NOT EXISTS idx_runtime_recovery_decisions_instance ON runtime_recovery_decisions(scenario, variant, created_at DESC); CREATE TABLE IF NOT EXISTS runtime_demand_leases ( lease_id TEXT PRIMARY KEY, scenario TEXT NOT NULL, variant TEXT NOT NULL DEFAULT 'live', consumer_id TEXT NOT NULL, kind TEXT NOT NULL, request_id TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, last_renewed_at TEXT NOT NULL, expires_at TEXT NOT NULL, status TEXT NOT NULL, stop_reason TEXT NOT NULL DEFAULT '', metadata_json TEXT NOT NULL DEFAULT '' ); CREATE INDEX IF NOT EXISTS idx_runtime_demand_leases_scenario ON runtime_demand_leases(scenario, variant, status, expires_at); CREATE INDEX IF NOT EXISTS idx_runtime_demand_leases_consumer ON runtime_demand_leases(consumer_id, status); CREATE TABLE IF NOT EXISTS runtime_editor_leases ( session_id TEXT PRIMARY KEY, harness TEXT NOT NULL DEFAULT '', agent TEXT NOT NULL DEFAULT '', pid INTEGER, host_boot_id TEXT NOT NULL DEFAULT '', working_dir TEXT NOT NULL DEFAULT '', scope TEXT NOT NULL DEFAULT '', containment_method TEXT NOT NULL DEFAULT '', claims_json TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL, created_at TEXT NOT NULL, last_heartbeat_at TEXT NOT NULL, heartbeat_deadline_at TEXT NOT NULL, stopped_at TEXT, stop_reason TEXT NOT NULL DEFAULT '', owner_kind TEXT NOT NULL DEFAULT '', owner_ref TEXT NOT NULL DEFAULT '', owner_evidence_json TEXT NOT NULL DEFAULT '', owner_source TEXT NOT NULL DEFAULT '', owner_recorded_at TEXT, binding_id TEXT NOT NULL DEFAULT '' ); CREATE INDEX IF NOT EXISTS idx_runtime_editor_leases_status ON runtime_editor_leases(status); CREATE INDEX IF NOT EXISTS idx_runtime_editor_leases_working_dir ON runtime_editor_leases(working_dir); CREATE TABLE IF NOT EXISTS runtime_demand_idle_windows ( scenario TEXT NOT NULL, variant TEXT NOT NULL, last_used_at TEXT NOT NULL, idle_until TEXT NOT NULL, PRIMARY KEY (scenario, variant) ); CREATE TABLE IF NOT EXISTS runtime_demand_stops ( instance_id TEXT PRIMARY KEY, generation INTEGER NOT NULL, signaling_started INTEGER NOT NULL DEFAULT 0 CHECK (signaling_started IN (0, 1)), created_at TEXT NOT NULL, FOREIGN KEY(instance_id) REFERENCES runtime_instances(instance_id) ON DELETE CASCADE ); CREATE TABLE IF NOT EXISTS runtime_agent_session_reaps ( reap_id TEXT PRIMARY KEY, session_id TEXT NOT NULL DEFAULT '', scope TEXT NOT NULL DEFAULT '', owner_kind TEXT NOT NULL DEFAULT '', owner_ref TEXT NOT NULL DEFAULT '', owner_evidence_json TEXT NOT NULL DEFAULT '', liveness_detail TEXT NOT NULL DEFAULT '', memory_bytes INTEGER NOT NULL DEFAULT 0, swap_bytes INTEGER NOT NULL DEFAULT 0, tasks INTEGER NOT NULL DEFAULT 0, outcome TEXT NOT NULL, error TEXT NOT NULL DEFAULT '', initiator TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL ); CREATE INDEX IF NOT EXISTS idx_runtime_agent_session_reaps_created ON runtime_agent_session_reaps(created_at DESC); CREATE TABLE IF NOT EXISTS runtime_editor_lease_bindings ( binding_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, state TEXT NOT NULL, containment_state TEXT NOT NULL, intended_scope TEXT NOT NULL, scope TEXT NOT NULL, method TEXT NOT NULL, failure TEXT NOT NULL, pid INTEGER NOT NULL, uid INTEGER NOT NULL, host_boot_id TEXT NOT NULL, process_start TEXT NOT NULL, evidence_pid INTEGER NOT NULL, evidence_uid INTEGER NOT NULL, evidence_boot_id TEXT NOT NULL, evidence_process_start TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, ended_at TEXT ); CREATE INDEX IF NOT EXISTS idx_editor_bindings_session ON runtime_editor_lease_bindings(session_id, created_at); CREATE UNIQUE INDEX IF NOT EXISTS idx_editor_binding_active ON runtime_editor_lease_bindings(session_id) WHERE state = 'active';
